import data from "@/content/testimonials.json";
import { interns, type Intern } from "@/lib/interns";

export type Testimonial = { name: string; role: string; quote: string[] };

// Generated by scripts/import-testimonials.mjs from the consented export only.
export const testimonials: Testimonial[] = data;

// Short, specific quotes rotated on the home page.
const FEATURED = [
  "Rasaq Ayomide",
  "Precious Kelechi Okafor",
  "Quadri Durodola",
  "Utibe Owoabasi Obot",
  "Muhammad Ibrahim",
  "Etigbue Adaeze Claret",
  "Hauwa Haruna Yahaya",
  "Kazeem Habeeb",
];
export const featuredTestimonials = FEATURED.map((n) => testimonials.find((t) => t.name === n)).filter(
  (t): t is Testimonial => !!t
);

const words = (s: string) => s.toLowerCase().split(/[^a-z]+/).filter((w) => w.length > 1);

/** The intern record for a testimonial author (for their headshot), matched on two shared names. */
export function internFor(name: string): Intern {
  const want = words(name);
  const match = interns.find((i) => {
    const have = new Set(words(i.name));
    return want.filter((w) => have.has(w)).length >= Math.min(2, want.length);
  });
  return match ?? { name, slug: words(name).join("-"), photo: null };
}
